static char *join(const char *const *lines)
{
    size_t n = 1;
    int i;
    char *s, *p;

    for (i = 0; lines[i]; i++) n += strlen(lines[i]) + 1;
    s = (char *)malloc(n);
    if (!s) return NULL;
    p = s;
    for (i = 0; lines[i]; i++) { size_t l = strlen(lines[i]); memcpy(p, lines[i], l); p += l; *p++ = '\n'; }
    *p = '\0';
    return s;
}

char *hks_builtin(const char *id)
{
    if (strcmp(id, "nethack367") == 0) return join(SCHEMA_nethack367);
    if (strcmp(id, "nethack5") == 0) return join(SCHEMA_nethack5);
    if (strcmp(id, "slashem") == 0) return join(SCHEMA_slashem);
    if (strcmp(id, "sporkhack") == 0) return join(SCHEMA_sporkhack);
    if (strcmp(id, "unnethack") == 0) return join(SCHEMA_unnethack);
    return NULL;
}
